WITH filtered AS (SELECT id, product_name, category, brand, cost, stock_qty, launch_date, tags, supplier_id, TRIM(brand) clean_brand, ARRAY_JOIN(tags, '|') tags_text, COALESCE(brand, 'UNKNOWN') brand_filled FROM products WHERE brand IS NOT NULL AND supplier_id IS NULL) SELECT s.* FROM filtered s WHERE EXISTS (SELECT 1 FROM inventory ch WHERE ch.product_id = s.id AND ch.product_id = 4);
